#include <vector>
#include <complex>
#include <algorithm>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) {
        return;
    }

    auto mag2 = [](const std::complex<double>& z) -> double {
        return std::norm(z);
    };

    auto lessByMagnitude = [&](const std::complex<double>& a,
                               const std::complex<double>& b) -> bool {
        const double na = mag2(a);
        const double nb = mag2(b);
        if (na < nb) return true;
        if (na > nb) return false;

        if (a.real() < b.real()) return true;
        if (a.real() > b.real()) return false;

        return a.imag() < b.imag();
    };

    // Parallel odd-even transposition sort.
    // In each phase, compared/swapped pairs are disjoint, so the loop is safe
    // to parallelize. The implicit barrier at the end of omp for ensures that
    // all swaps in one phase complete before the next phase starts.
    #pragma omp parallel
    {
        for (std::size_t phase = 0; phase < n; ++phase) {
            const std::size_t start = phase % 2;

            #pragma omp for schedule(static)
            for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
                 i < static_cast<std::ptrdiff_t>(n - 1);
                 i += 2) {
                std::complex<double> &a = x[static_cast<std::size_t>(i)];
                std::complex<double> &b = x[static_cast<std::size_t>(i + 1)];
                if (lessByMagnitude(b, a)) {
                    std::swap(a, b);
                }
            }
        }
    }
}
